func TestApplyEntryRejectsDuplicates(t *testing.T) {
	l := sample()
	if err := ApplyEntry(l, Entry{ID: "e1", Account: "cash", Amount: 1}); err != ErrDuplicate {
		t.Fatalf("duplicate accepted: %v", err)
	}
}

